settings.css:
/* Base form styling */
.foundry-form input, .foundry-form textarea, .foundry-form select {
    background-color: rgb(21, 18, 13) !important;
    color: rgb(243, 238, 228) !important;
    border: 1px solid rgba(200, 162, 76, 0.18) !important;
    border-radius: 0px !important;
    padding: 14px 16px !important;
    font-size: 15px !important;
    font-family: Jost, sans-serif !important;
    font-weight: 300 !important;
    line-height: normal !important;
    box-shadow: none !important;
}

.foundry-form input::placeholder, .foundry-form textarea::placeholder {
    color: rgba(243, 238, 228, 0.5) !important;
    opacity: 1 !important;
}

/* Label & Typography styling */
.foundry-form .ff-label, .foundry-form .ff-choice {
    color: rgb(182, 169, 143) !important;
    font-size: 12px !important;
    font-weight: 500 !important;
    letter-spacing: 1.68px !important;
    text-transform: uppercase !important;
    font-family: Jost, sans-serif !important;
}

/* Make asterisks visible and match the label color */
.foundry-form .ff-req {
    display: none !important;

}

/* Form Container - Transparent to blend with outer div */
#ffm-form-4v5ta.foundry-form {
    background: transparent !important;
    padding: 0 !important;
    border-radius: 0 !important;
    display: flex;
    flex-direction: column;
}

/* Reorder elements to place disclaimer at the bottom */
.foundry-form .ff-page { order: 1; }
.foundry-form .ff-msg { order: 2; }
.foundry-form .ff-submit { 
    order: 3; 
    margin-top: 15px; 
    margin-bottom: 12px;
}
.foundry-form .ff-header { 
    order: 4; 
    margin: 0;
}

/* Hide duplicate title inside the form */
.foundry-form .ff-header .ff-form-title {
    display: none;
}

/* Style bottom disclaimer text */
.foundry-form .ff-header .ff-form-desc {
    color: #8c867a;
    font-family: 'Jost', sans-serif;
    font-size: 14px;
    font-weight: 300;
}

/* 2-Column Layout for Specific Fields */
.foundry-form .ff-field.ff-half {
    flex: 1 1 calc(50% - 9px) !important;
    max-width: calc(50% - 9px);
}

/* Checkbox Grid (Products) */
.foundry-form [data-fid="pv81ar6"] {
    display: grid;
    grid-template-columns: 1fr 1fr;
    row-gap: 16px;
    column-gap: 12px;
}

/* Radio Button Row (Contact Method) */
.foundry-form [data-fid="aygu0u3"] {
    display: flex;
    flex-direction: row;
    gap: 30px;
}

/* Submit Button */
.foundry-form .ff-submit {
    width: 100%;
    background-color: #c8a24c !important;
    color: #15120d !important;
    border-radius: 0 !important;
    font-family: 'Jost', sans-serif !important;
    text-transform: uppercase;
    font-weight: 600 !important;
    letter-spacing: 2px;
    font-size: 14px;
    padding: 18px !important;
    transition: opacity 0.2s ease;
}

.foundry-form .ff-submit:hover {
    opacity: 0.9;
}
